  Corollary wrap_strlen_run : forall regs,
    getr regs 10 = Z_to_bv 64 p -> getr regs 2 = sp -> getr regs 1 = ra ->
    exists regs' M',
      msteps ASEGS (mkst regs (0x64518 : word) mem0 rom) (mkst regs' ra M' rom)
